<?php partial('account_nav',['route'=>$route]); ?><section class="profile-hero panel glass section"><?= avatar($me,'large') ?><div class="grow"><span class="eyebrow">YOUR CORNER OF THE ISLAND</span><h1><?= e($me['display_name']) ?><?php if ($me['verified']): ?><?= icon('shield') ?><?php endif ?></h1><p>@<?= e($me['username']) ?> &middot; <?= t('Joined') ?> <?= dt((int)$me['created_at']) ?></p></div><div class="profile-actions row wrap"><?php if ($s->enabled('submissions') || $a->auth->can('content')): ?><a class="btn" href="<?= e(url('write')) ?>"><?= icon('edit') ?><?= t('Write a story') ?></a><?php endif ?><?php if ($a->auth->can('admin')): ?><a class="btn secondary" href="<?= e(au()) ?>"><?= icon('grid') ?><?= t('Dashboard') ?></a><?php endif ?></div></section><?php partial('badge_collection',['badgeUser'=>(int)$me['id']]); ?><div class="two-column section"><section class="panel glass"><h2><?= t('A little about you') ?></h2><?= form_start('profile') ?><?php field('display_name','Display name',$me['display_name'],'text',['required'=>'required','maxlength'=>'100']);field('bio','Your bio',$me['bio'],'textarea',['maxlength'=>'1000']);upload_field('avatar_id','Avatar image ID',(int)$me['avatar_id']);button(); ?></form></section><section class="panel glass"><h2><?= t('Account security') ?></h2><?= form_start('password') ?><?php field('current_password','Current password','','password',['required'=>'required','autocomplete'=>'current-password']);field('password','New password (12+ characters, letters and digits)','','password',['required'=>'required','minlength'=>'12','maxlength'=>'72','autocomplete'=>'new-password']);button('Update password','secondary full','lock'); ?></form><p class="hint"><?= t('A password change invalidates other sessions and existing recovery links.') ?></p><?= form_start('logout') ?><?php button('Sign out','ghost full','logout'); ?></form></section></div>
<?php $own=$a->db->all('SELECT id,title,kind,status,created_at FROM cy_contents WHERE author_id=? ORDER BY id DESC LIMIT 30',[(int)$me['id']]); ?><section class="panel section"><div class="section-heading"><h2><?= t('Your contributions') ?></h2><span class="hint"><?= t('Latest 30 entries') ?></span></div><div class="mini-list"><?php foreach ($own as $entry): ?><div class="row between wrap"><a href="<?= e(item_url($entry)) ?>"><?= e($entry['title']) ?></a><span class="pill"><?= t($entry['status']) ?></span><a class="text-link" href="<?= e(url('write',['id'=>$entry['id']])) ?>"><?= t('Edit') ?><?= icon('edit') ?></a></div><?php endforeach ?><?php if (!$own) {empty_state('Your first story starts with one thought.','edit');} ?></div></section>
<?php if ($s->enabled('shop')): ?><section class="panel section"><div class="section-heading"><h2><?= t('Your shipping addresses') ?></h2><?= icon('box') ?></div><?php foreach ($a->db->all('SELECT * FROM cy_addresses WHERE user_id=? ORDER BY id DESC',[(int)$me['id']]) as $address): ?><div class="address-card"><div><strong><?= e($address['recipient']) ?></strong> <span><?= e($address['phone']) ?></span><p><?= e($address['address']) ?></p></div><?= form_start('address_delete') . hidden('id',$address['id']) ?><?php button('Delete','ghost small','close'); ?></form></div><?php endforeach ?><?= form_start('address_save') ?><div class="fields-grid"><?php field('recipient','Recipient name','','text',['required'=>'required']);field('phone','Phone','','tel',['required'=>'required']); ?></div><?php field('address','Full shipping address','','textarea',['required'=>'required','maxlength'=>'1000']);button('Add address','secondary','plus'); ?></form></section><?php endif ?>

<?php if($s->enabled('smtp')): ?><section class="panel glass section"><div class="section-heading"><div><span class="eyebrow">IDENTITY / EMAIL</span><h2><?= t('Verify or change your email') ?></h2></div><span class="pill"><?= t((int)$me['email_verified_at']>0?'Email verified':'Email not verified') ?></span></div>
